import React, { useState, useEffect, useMemo } from 'react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { supabase } from './supabaseClient';
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import ConflictTable from './components/ConflictTable';
import GlobalResourceMonitor from './components/GlobalResourceMonitor';
import {
  LayoutDashboard, Printer, Activity, Zap, LogOut, Lock, User, 
  RefreshCw, Globe, Calendar, List, Users, Shield, UserPlus, Trash2, Archive, CheckCircle, Plus, Clock, AlertOctagon, Download, Bell, BellRing, AlertTriangle, X
} from 'lucide-react';

// --- NOTIFICATION PANEL (ACCORD STYLED) ---
const NotificationPanel = ({ notifications, onClose, onMarkRead }) => {
  const unread = notifications.filter(n => !n.is_read).length;

  return (
    <div className="fixed inset-y-0 right-0 w-full max-w-md bg-slate-50 shadow-[0_0_100px_rgba(0,0,0,0.3)] z-[200] flex flex-col animate-in slide-in-from-right-full duration-500 border-l-[8px] border-blue-600">
      <div className="bg-slate-900 p-10 flex justify-between items-center text-white">
        <div>
          <h3 className="text-3xl font-black uppercase tracking-tighter flex items-center gap-3">
            <Bell className="text-blue-500" size={28} /> Action <span className="text-blue-500 italic">Logs</span>
          </h3>
          <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mt-2">{unread} Unread Alerts</p>
        </div>
        <button onClick={onClose} className="bg-white/10 p-3 rounded-2xl hover:bg-rose-500 transition-all active:scale-95"><X size={20}/></button>
      </div>
      <div className="flex-1 overflow-y-auto p-8 space-y-4 custom-scrollbar">
        {notifications.length === 0 && <div className="text-center py-20 text-slate-400 font-black uppercase text-xs tracking-widest">System Quiet</div>}
        {notifications.map(n => (
          <div key={n.id} onClick={() => onMarkRead(n.id)} className={`p-6 rounded-[2rem] border-2 cursor-pointer transition-all ${n.is_read ? 'bg-white border-slate-100 opacity-60' : n.type === 'urgent' ? 'bg-rose-50 border-rose-200 shadow-md hover:border-rose-400 hover:shadow-lg' : 'bg-white border-blue-200 shadow-lg hover:border-blue-400'}`}>
            <div className="flex justify-between items-start mb-3">
               <h4 className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2 ${n.type === 'urgent' ? 'text-rose-600' : 'text-blue-600'}`}>
                 {n.type === 'urgent' && <div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"/>}
                 {!n.is_read && n.type !== 'urgent' && <div className="w-2 h-2 rounded-full bg-blue-500"/>}
                 {n.title}
               </h4>
               <span className="text-[8px] font-black text-slate-400 uppercase">{new Date(n.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
            </div>
            <p className="text-xs font-bold text-slate-700 leading-relaxed">{n.message}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

// --- 1. USER REGISTRY COMPONENT ---
const UserRegistry = ({ profiles, onBlock, onArchive, onDelete, onCreate, currentRole, onView }) => {
  const [searchTerm, setSearchTerm] = React.useState("");
  const isHead = currentRole === 'HEAD_ADMIN';

  const filteredProfiles = profiles.filter(p => 
    (p.full_name || "").toLowerCase().includes(searchTerm.toLowerCase()) || 
    (p.email || "").toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="bg-white border-2 border-slate-100 rounded-[3rem] overflow-hidden shadow-2xl mb-16 animate-in fade-in slide-in-from-bottom-8 duration-700">
      <div className="bg-slate-900 p-10 flex justify-between items-center border-b-8 border-blue-600">
        <div>
          <h3 className="text-white text-3xl font-black uppercase tracking-tighter flex items-center gap-3">
            <Shield className="text-blue-500" size={28} /> System <span className="text-blue-500 italic">Registry</span>
          </h3>
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest mt-1">
            {isHead ? 'Global Account Control' : 'Departmental Proctor Management'}
          </p>
        </div>
        <button 
          onClick={onCreate}
          className="bg-blue-600 hover:bg-blue-500 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl transition-all active:scale-95 flex items-center gap-2"
        >
          <UserPlus size={18} /> {isHead ? 'Create Dept Head' : 'Create Proctor'}
        </button>
      </div>

      <div className="p-8">
        <div className="mb-6">
          <input 
            type="text" 
            placeholder="Search users by name or email..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 p-5 rounded-2xl font-black text-xs border-2 border-slate-100 outline-none focus:border-blue-500"
          />
        </div>
        <table className="w-full text-left border-separate border-spacing-y-3">
          <thead>
            <tr className="text-[10px] font-black uppercase text-slate-400">
              <th className="px-6 py-4">User Identity</th>
              <th className="px-6 py-4">Access Level</th>
              <th className="px-6 py-4">Assignment</th>
              <th className="px-6 py-4">Status</th>
              <th className="px-6 py-4 text-right">Administrative Actions</th>
            </tr>
